head.b:skin:
/* Monika by AOW.VN - Blogspot template (wap nhe, PC rong gon, luoi anh game)
   Banner va danh sach: web va app Java dung chung du lieu qua api.justmonika.top
   Luoi dung float + padding-top (khong flex/grid/aspect-ratio) de Opera Mini 6 tren Nokia chay duoc */
*{box-sizing:border-box}
body{margin:0;background:#1b0a38;color:#fff;font:15px/1.45 system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif}
a{color:inherit;text-decoration:none}
img{max-width:100%;height:auto}
h1,h2,h3{margin:0}
.wrap{max-width:1080px;margin:0 auto}
/* header: to tren dien thoai/Nokia, gon tren PC */
.hd{background:#2b0f4f;background:linear-gradient(135deg,#2b0f4f,#4c1466);position:relative;overflow:hidden}
.hd-in{position:relative;z-index:1;padding:12px}
.brand{margin-bottom:10px}
.logo{display:block;font-size:30px;font-weight:700;letter-spacing:.3px;line-height:1.1}
.logo b{color:#ff7a1a}
.tag,.by{margin:2px 0 0;font-size:12px;color:#cdbfe8}
.by b{color:#ff7a1a}
.vn{background:#fff;color:#2b0f4f;font-weight:700;border-radius:3px;padding:0 4px;margin-left:3px;font-size:11px}
.curve{position:absolute;right:0;bottom:0;width:62%;max-width:560px;height:75%;z-index:0}
.hb .curve{display:none}
/* banner: an khi chua co, hien dung ti le 4:1 khi da nap */
.bn{display:none}
.bn.on{display:block;position:relative;height:0;padding-top:25%;overflow:hidden;border-radius:4px}
.bn.on a,.bn.on div,.bn.on img{position:absolute;left:0;top:0;width:100%;height:100%;display:block}
.bn.on img{object-fit:contain}
.bn-top2{display:none!important}
.bn-item,.bn-foot{margin:12px auto;max-width:640px}
.bn-list.on{padding-top:83%}
.bn-list{margin:0 0 12px}
.adslot .widget{margin:0 0 12px}
/* nav: 4 o ngang tren man nho */
.nav{background:#140729;overflow:hidden}
.nav a{float:left;width:33.333%;padding:7px 2px 6px;text-align:center;font-size:12px;line-height:1.2;background:#250e48;border-bottom:1px solid #3a1a66}
.nav a:nth-child(even){background:#290f4f}
.nav a.on,.nav a:hover{background:#cc580c;background:linear-gradient(#cc580c,#b44606);font-weight:700}
.nav svg{display:block;margin:0 auto 2px;width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.nav .go{display:none}
.cr{display:inline-block;width:0;height:0;margin-left:4px;border:4px solid transparent;border-top-color:#cdbfe8;border-bottom:0;vertical-align:middle}
.sf{display:flex;gap:6px;overflow:hidden;padding:8px 12px;background:#140729}
.sf input{float:left;width:68%;flex:1;min-width:0;padding:8px 10px;border:1px solid #4a2a7a;border-radius:4px;background:#1f0b3d;color:#fff;font:inherit}
.sf button{float:right;padding:8px 14px;border:0;border-radius:4px;background:#cc580c;background:linear-gradient(#cc580c,#b44606);color:#fff;font:inherit;font-weight:700;cursor:pointer}
/* tieu de muc + luoi game: 2 o moi hang tren Nokia/dien thoai */
.st,.widget>h2{padding:8px 12px;background:#cc580c;background:linear-gradient(90deg,#cc580c,#b44606);font-size:14px;font-weight:700}
.gl{overflow:hidden}
.gc{float:left;width:50%;padding:8px 4px 0}
.gcb{background:#250e48;border:1px solid #3a1a66;border-radius:8px;overflow:hidden}
.gc:hover .gcb{border-color:#ff7a1a}
.th{display:block;position:relative;height:0;padding-top:75%;overflow:hidden;background:#4c1466;background:linear-gradient(135deg,#4c1466,#cc580c)}
.th.has{background:#140729}
.th .sc{position:absolute;left:0;right:0;top:0;bottom:0;margin:auto;max-width:100%;max-height:100%;display:block}
.th .ph{position:absolute;left:0;right:0;top:50%;margin-top:-.6em;text-align:center;font-size:34px;line-height:1.2;font-weight:700;color:rgba(255,255,255,.55)}
.th .ic2{position:absolute;left:5px;bottom:5px;width:32px;height:32px;border-radius:7px;border:2px solid #fff;background:#3b1a6b;display:block}
.th .ic1{position:absolute;left:50%;top:50%;width:56px;height:56px;margin:-28px 0 0 -28px;border-radius:12px;background:#3b1a6b;display:block}
.bd{position:absolute;right:5px;top:5px;font-size:10px;line-height:1.6;font-weight:700;padding:0 6px;border-radius:8px;background:#dc1a70;color:#fff}
.bd.h{background:#cc580c}
.gt{padding:6px 7px 7px}
.gt h2{height:2.6em;overflow:hidden;font-size:13px;line-height:1.3}
.gt h2 a:hover{color:#ff7a1a}
.chips{margin:3px 0 0;max-height:42px;overflow:hidden}
.gt .chips{height:40px}
.chips span,.chips a{display:inline-block;max-width:100%;font-size:11px;line-height:17px;padding:0 6px;margin:0 3px 2px 0;border-radius:8px;background:#3b1a6b;color:#cdbfe8}
.chips .v{background:#dc1a70;color:#fff}
.dt{font-size:11px;color:#a58bd0}
.it .chips{height:auto;white-space:normal;margin:6px 0}
.it .chips a,.it .chips span{margin:0 4px 4px 0}
.raw{display:none}
.emp{padding:20px 12px;text-align:center;color:#cdbfe8}
.pg{overflow:hidden;margin-top:8px;padding:8px 12px;background:#140729;color:#ff7a1a;font-weight:700}
.pg a{float:left}
.pg a.o{float:right}
/* huy hieu the (VH, MOD, 3D, VN...) va luot tai */
.chips .tg,.it .chips .tg{background:#ffd23f;color:#2a1800;font-weight:700}
.dlc{position:absolute;right:5px;bottom:5px;font-size:10px;line-height:1.6;padding:0 6px;border-radius:8px;background:rgba(0,0,0,.72);color:#fff}
/* menu tha xuong (the loai tu API; khong co JS thi menu van la link nhan) */
.nav .cr{margin-left:3px;font-size:11px}
.dd{display:none;background:#140729;border-top:1px solid #3a1a66;border-bottom:2px solid #cc580c}
.dd.on{display:block}
.dd-in{overflow:hidden}
.dd a{float:left;width:50%;padding:9px 12px;font-size:13px;line-height:1.3;border-bottom:1px solid #3a1a66}
.dd a:hover{background:#290f4f;color:#ff7a1a}
.dd a.all{width:100%;font-weight:700;color:#ff7a1a}
.dd a span{color:#cdbfe8;font-size:11px;margin-left:3px}
.dd p{margin:0;padding:9px 12px;color:#cdbfe8;font-size:13px}
/* trang chu: De xuat hom nay + Top tai nhieu (float, khong flex/grid) */
.hm .st,.tp .st{margin-top:8px}
.stm{float:right;font-size:12px;font-weight:400;color:#ffe2c9}
.hm .gl .gc{padding-bottom:0}
.tpt{overflow:hidden;background:#140729}
.tpt a{float:left;width:33.333%;padding:8px 2px;text-align:center;font-size:12px;line-height:1.2;background:#250e48;border-bottom:2px solid #3a1a66}
.tpt a:nth-child(even){background:#290f4f}
.tpt a.on{background:#b44606;border-bottom-color:#ff7a1a;font-weight:700}
.tpr{display:block;overflow:hidden;padding:6px 10px;background:#250e48;border-bottom:1px solid #3a1a66}
.tpr:nth-child(odd){background:#290f4f}
.tpr:hover{background:#3a1a66}
.tpn{float:left;width:24px;height:24px;margin:8px 8px 0 0;line-height:22px;text-align:center;border-radius:12px;font-size:12px;font-weight:700;background:#3b1a6b;color:#fff;border:1px solid #8f78bd}
.tpn.r1{background:#ffd23f;color:#2a1800;border-color:#fff3b0}
.tpn.r2{background:#dde1e7;color:#14161a;border-color:#fff}
.tpn.r3{background:#e0954f;color:#1c0d00;border-color:#ffd9b0}
.tpi{float:left;width:40px;height:40px;margin:0 8px 0 0;border-radius:8px;background:#3b1a6b;overflow:hidden}
.tpi img{display:block;width:40px;height:40px;border:0}
.tpd{float:right;margin:12px 0 0 6px;font-size:11px;color:#cdbfe8}
.tpx{display:block;overflow:hidden}
.tpx b{display:block;max-height:2.6em;overflow:hidden;font-size:13px;line-height:1.3;font-weight:400}
.tpx i{display:block;font-size:11px;font-style:normal;color:#a58bd0;height:1.3em;overflow:hidden}
.tpr:hover b{color:#ff7a1a}
.tpm{display:block;padding:9px 12px;text-align:center;color:#ff7a1a;font-weight:700;background:#140729}
.tpe{padding:14px 12px;text-align:center;color:#cdbfe8;font-size:13px;background:#250e48}
/* phan trang so: 1 2 3 4 5 6 ... cuoi (JS dung tu Worker /v1/pager.json; khong co JS van con lien ket Moi hon / Cu hon) */
.pn{display:none;overflow:hidden;margin-top:8px;padding:6px 4px 2px;background:#140729;text-align:center}
.pn.on{display:block}
.pn a,.pn span{display:inline-block;min-width:34px;height:34px;line-height:32px;margin:0 2px 4px;padding:0 6px;border-radius:6px;background:#250e48;border:1px solid #3a1a66;font-size:14px;font-weight:700;color:#fff}
.pn a:hover{border-color:#ff7a1a;color:#ff7a1a}
.pn span.cur{background:#cc580c;background:linear-gradient(#cc580c,#b44606);border-color:#ff7a1a}
.pn span.dot{background:none;border:0;min-width:16px;padding:0;color:#a58bd0}
.pg.hide{display:none}
/* trang Xep hang */
.it.rkp{padding:12px 0}
.it.rkp .pt{padding:0 12px 10px}
.rk .nj{padding:20px 12px}
.rk .nj a{color:#ff7a1a;text-decoration:underline}
.js .rk .nj{display:none}
.rk .tabs{overflow:hidden}
.rk .tabs a{float:left;width:20%;padding:9px 1px;text-align:center;font-size:12px;line-height:1.2;background:#250e48;border-bottom:2px solid #3a1a66}
.rk .tabs a:nth-child(even){background:#290f4f}
.rk .tabs a.on{background:#b44606;border-bottom-color:#ff7a1a;font-weight:700}
.rk .fl{padding:8px 12px 0;overflow:hidden}
.rk .fl b{display:block;font-size:11px;font-weight:400;color:#cdbfe8;margin-bottom:3px}
.rk .fb{display:inline-block;margin:0 4px 6px 0;padding:0 10px;line-height:26px;font-size:12px;border-radius:13px;background:#3b1a6b;color:#cdbfe8}
.rk .fb.on{background:#ff7a1a;color:#1b0a38;font-weight:700}
.rk .emp a{color:#ff7a1a;text-decoration:underline}
.it .rk .chips{height:19px;white-space:nowrap;margin:3px 0 0}
.it .rk .chips a,.it .rk .chips span{margin:0 3px 0 0}
.rkn{position:absolute;left:5px;top:5px;min-width:26px;height:26px;padding:0 5px;line-height:26px;text-align:center;border-radius:13px;font-size:13px;font-weight:700;background:#3b1a6b;color:#fff;border:1px solid #8f78bd}
.rkn.r1{background:#ffd23f;color:#2a1800;border-color:#fff3b0}
.rkn.r2{background:#dde1e7;color:#14161a;border-color:#fff}
.rkn.r3{background:#e0954f;color:#1c0d00;border-color:#ffd9b0}
/* item */
.it{background:#250e48;padding:12px}
.pt{font-size:22px;line-height:1.25}
.pb{margin-top:10px;word-wrap:break-word;overflow-wrap:break-word}
.pb a{color:#ff7a1a;text-decoration:underline}
.pb img{border-radius:4px}
.dlbox{margin:8px 0 14px;padding:10px;background:#290f4f;border:1px solid #3a1a66;border-radius:6px;overflow:hidden}
.gic{float:right;margin:0 0 6px 10px;border-radius:12px;image-rendering:pixelated;background:#3b1a6b}
.info{border-collapse:collapse;width:100%;margin-bottom:10px}
.info th{width:38%;text-align:left;color:#cdbfe8;font-weight:400;padding:3px 0}
.info td{padding:3px 0}
.pb a.dlbtn{display:block;text-align:center;padding:12px;border-radius:6px;background:#cc580c;background:linear-gradient(#cc580c,#b44606);color:#fff;font-weight:700;font-size:16px;text-decoration:none}
.pb a.dlbtn:hover{filter:brightness(1.15)}
.nojs pre.mk-meta{display:block;white-space:pre-wrap;font:12px monospace;background:#1f0b3d;padding:8px;border-radius:4px}
pre.mk-meta{display:none}
/* widgets, footer */
.widget{margin:0 0 12px}
.widget ul{list-style:none;margin:0;padding:0}
.widget li{display:flex;justify-content:space-between;gap:8px;overflow:hidden;padding:9px 12px;background:#250e48;border-bottom:1px solid #3a1a66}
.widget li:nth-child(even){background:#290f4f}
.widget li a:hover{color:#ff7a1a}
.widget li span{float:right;color:#cdbfe8;font-size:12px}
.ft{background:#140729;margin-top:12px;padding:12px;text-align:center;color:#cdbfe8;font-size:12px}
.ft a{text-decoration:underline}
.ft .widget{margin:0}
.ft .widget li{text-align:center;background:none;border:0;justify-content:center;padding:2px}
/* tablet: 3 o moi hang */
@media (min-width:600px){
.cols{padding:12px}
.gc{width:33.333%}
.gt h2{font-size:14px}
.main,.side{border-radius:6px;overflow:hidden}
}
/* PC: header gon mot hang (logo + menu + tim kiem), banner dau trang chuyen xuong cot noi dung, 4 o moi hang */
@media (min-width:900px){
.top{position:sticky;top:0;z-index:10;background:#2b0f4f;background:linear-gradient(90deg,#2b0f4f,#4c1466);box-shadow:0 2px 10px rgba(0,0,0,.45)}
.top-in{max-width:1080px;margin:0 auto;padding:0 12px;height:52px;display:flex;align-items:center}
.hd{background:none;overflow:visible;flex:none}
.hd-in{padding:0}
.brand{margin:0;display:flex;align-items:center}
.logo{font-size:26px}
.tag,.curve,.hd .bn-top{display:none}
.by{margin:0 0 0 10px}
.bar{flex:1;min-width:0;display:flex;align-items:center;margin-left:22px}
.nav{background:none;overflow:visible;display:flex}
.nav a{float:none;width:auto;display:flex;align-items:center;padding:7px 11px;margin-right:2px;font-size:14px;background:none;border:0;border-radius:6px;text-align:left}
.nav a:nth-child(even){background:none}
.nav a.on,.nav a:hover{background:#cc580c;background:linear-gradient(#cc580c,#b44606)}
.nav svg{display:none}
.sf{margin-left:auto;padding:0;background:none;width:220px}
.by{display:none}
.dd{position:absolute;left:0;right:0;top:100%;box-shadow:0 8px 14px rgba(0,0,0,.5)}
.dd-in{max-width:1080px;margin:0 auto;padding:6px 12px}
.dd a{width:25%;border:0;border-radius:4px}
.dd a.all{width:100%}
.rk .tabs a{width:auto;float:none;display:inline-block;padding:9px 18px}
.it.rkp .pt{padding:0 18px 10px}
.it.rkp .rk .fl{padding:8px 18px 0}
.sf input{padding:6px 10px}
.sf button{float:right;padding:6px 12px}
.cols{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:12px;padding:12px;align-items:start}
.bn-top2.on{display:block!important;max-width:520px;margin:0 0 12px}
.gc{width:25%}
.gt h2{font-size:14px}
.it{padding:18px}
.pt{font-size:26px}
.pb a.dlbtn{display:inline-block;padding:12px 28px}
}
@media (min-width:1060px){
.by{display:block}
.sf{width:240px}
}

body.script:
//
(function(){
var d=document,vw=d.documentElement.clientWidth||window.innerWidth||320,
 API=(location.protocol==='https:'?'https:':'http:')+'//api.justmonika.top';
d.documentElement.className=d.documentElement.className.replace('nojs','js');
function $$(s,r){return Array.prototype.slice.call((r||d).querySelectorAll(s))}
function el(t,c,x){var e=d.createElement(t);if(c)e.className=c;if(x!=null)e.textContent=x;return e}
function del(e){if(e&&e.parentNode)e.parentNode.removeChild(e)}
function clr(e){while(e.firstChild)e.removeChild(e.firstChild)}
/* GET JSON bang XHR (Opera Mini 6 khong co fetch). API cho phep CORS */
function get(u,ok,er){
 var x=new XMLHttpRequest();
 x.onreadystatechange=function(){
  if(x.readyState!==4)return;
  var j=null;if(x.status>=200&&x.status<300){try{j=JSON.parse(x.responseText)}catch(e){}}
  if(j!==null)ok(j);else if(er)er()};
 x.open('GET',u,true);x.send(null)}
/* du lieu dung chung, moi loai chi tai mot lan */
var Q={};
function once(k,u,cb){
 var q=Q[k]||(Q[k]={w:[]});
 if(q.done){cb(q.v);return}
 q.w.push(cb);if(q.w.length>1)return;
 get(API+u,function(v){q.done=1;q.v=v;var w=q.w;q.w=[];for(var i=0;i<w.length;i++)w[i](v)},
  function(){q.done=1;q.v=null;var w=q.w;q.w=[];for(var i=0;i<w.length;i++)w[i](null)})}
function meta(pre){
 var t=pre.innerHTML.replace(/<br\s*\/?>/gi,'\n').replace(/<\/(p|div)>/gi,'\n').replace(/<[^>]+>/g,''),
  x=el('textarea');x.innerHTML=t;t=x.value;
 var m={};t.split(/\n/).forEach(function(l){var i=l.indexOf(':');if(i>0)m[l.slice(0,i).trim().toLowerCase()]=l.slice(i+1).trim()});
 return m}
function sz(k){k=parseInt(k,10);if(!k)return'';return k>=1024?(k/1024).toFixed(1)+' MB':k+' KB'}
function pad(n){return('0'+n).slice(-2)}
function fd(t){var x=new Date(t);return isNaN(x.getTime())?'':pad(x.getDate())+'/'+pad(x.getMonth()+1)+'/'+x.getFullYear()}
/* luot tai: <5 an, <1000 so that, tu 1000 dang 1,2k */
function fdl(n){n=parseInt(n,10)||0;if(n<5)return'';if(n<1000)return''+n;var k=Math.floor(n/100)/10;return String(k).replace('.',',')+'k'}
/* the: slug taxonomy hoac nhan ngan -> huy hieu */
var TG={vh:'VH','viet-hoa':'VH',mod:'MOD','3d':'3D',vn:'VN','game-viet':'VN',touch:'TOUCH','cam-ung':'TOUCH',mp:'MP','nhieu-nguoi':'MP',net:'NET','can-mang':'NET'};
var PL={j2me:'Java J2ME',s60v2:'Symbian S60 v1/v2',s60v3:'Symbian S60 v3',s60v5:'Symbian S60 v5',s3:'Symbian^3 / Belle'};
function tg(s){return TG[String(s).toLowerCase().replace(/^\s+|\s+$/g,'')]||''}
function tgList(s){var o=[],a=String(s||'').split(/[,;]/),i,t;for(i=0;i<a.length;i++){t=tg(a[i]);if(t&&o.indexOf(t)<0)o.push(t)}return o}
/* them huy hieu vao dau hang chip, bo qua cai da co */
function addTags(ch,list){
 var have={},i;$$('.tg',ch).forEach(function(e){have[e.textContent]=1});
 for(i=list.length-1;i>=0;i--)if(!have[list[i]]){ch.insertBefore(el('span','tg',list[i]),ch.firstChild)}
 var t=$$('.tg',ch);for(i=t.length-1;i>=0;i--)ch.insertBefore(t[i],ch.firstChild)}
/* anh Google/Blogger: thu nho vua khung (giu ti le, khong cat/meo), anh ngoai giu nguyen va CSS thu ve vua o */
function gimg(u,w,h){
 if(!/googleusercontent|blogspot|ggpht/i.test(u))return u;
 var s='w'+w+'-h'+h;
 if(/=[swh]\d[^\/]*$/i.test(u))return u.replace(/=[swh]\d[^\/]*$/i,'='+s);
 if(/\/[swh]\d+[^\/]*\/[^\/]+$/i.test(u))return u.replace(/\/[swh]\d+[^\/]*\/([^\/]+)$/i,'/'+s+'/$1');
 return u}
/* may cu khong bat tay duoc HTTPS: anh/link cua api.justmonika.top di theo giao thuc cua trang (http tren trang http) */
function lo(u){return u?u.replace(/^https?:\/\/api\.justmonika\.top/i,API):u}
function fileKey(m){return m.file&&/^[0-9a-f]{10}$/i.test(m.file)?m.file.toLowerCase():((/\/v1\/f\/[^\/?#]*-([0-9a-f]{10})\.jar/i.exec(m.jar||'')||[])[1]||'').toLowerCase()}
/* luot tai theo duong dan bai: id lay tu icons.json (/v1/ic/<id>-64.png); bai chua co id thi hoi stats.json?paths= (Worker tra {"<duong dan>":{"id":..,"dl":..}}) */
function fillDl(list){
 if(!list.length)return;
 once('icons','/v1/icons.json',function(M){
  M=M||{};
  var byId={},ids=[],rest=[],i,x,m;
  for(i=0;i<list.length;i++){x=list[i];m=/\/v1\/ic\/(\d+)-/.exec(M[x.path]||'');
   if(m){if(!byId[m[1]]){byId[m[1]]=[];ids.push(m[1])}byId[m[1]].push(x)}else rest.push(x)}
  if(ids.length)get(API+'/v1/stats.json?ids='+ids.slice(0,50).join(','),function(S){
   for(var k in byId){if(S&&S[k])for(var j=0;j<byId[k].length;j++)byId[k][j].set(S[k].dl)}});
  if(rest.length){var ps=[];for(i=0;i<rest.length&&i<50;i++)ps.push(rest[i].path);
   get(API+'/v1/stats.json?paths='+encodeURIComponent(ps.join(',')),function(S){
    for(var j=0;j<rest.length;j++){var r=S&&S[rest[j].path];if(r)rest[j].set(r.dl)}})}})}
/* ngay dang (trang bai) */
$$('.dt').forEach(function(e){e.textContent=fd(e.getAttribute('data-t'))});
/* menu dang chon */
$$('.nav a').forEach(function(a){if(!a.hash&&a.pathname.replace(/^\/?/,'/')===location.pathname)a.className=(a.className?a.className+' ':'')+'on'});
/* menu nhom: Game / Phan mem / Giao dien / Am thanh / Truyen & Meo, danh sach the loai lay tu /v1/menu.json (nhom + the loai co bai), moi muc la link nhan Blogger */
var dd=d.getElementById('dd'),ddin=d.getElementById('dd-in'),ddk='';
function lab(n){return '/search/label/'+encodeURIComponent(n)}
function kindOf(M,k){var i;if(M&&M.kinds)for(i=0;i<M.kinds.length;i++)if(String(M.kinds[i].kind)===k)return M.kinds[i];return null}
function ddFill(k,M){
 clr(ddin);
 var K=kindOf(M,k),all=el('a','all',K?'Tất cả '+K.name:'Tất cả');
 all.href=lab(K?K.label:({1:'Game',2:'App',3:'Bài viết',4:'Giao diện',5:'Âm thanh'})[k]||'');ddin.appendChild(all);
 if(!K){ddin.appendChild(el('p','',M===null?'Chưa tải được thể loại.':'Đang tải thể loại...'));return}
 if(k==='1'){var vh=el('a','','Game Việt hóa');vh.href=lab('VH');ddin.appendChild(vh)}
 K.cats.forEach(function(c){
  var a=el('a','',c.name);a.href=lab(c.name);
  if(c.count)a.appendChild(el('span','',String(c.count)));ddin.appendChild(a)});
 if(!K.cats.length)ddin.appendChild(el('p','','Chưa có bài trong nhóm này.'))}
function ddClose(){if(!dd)return;dd.className=dd.className.replace(' on','');ddk='';$$('.nav a[data-dd]').forEach(function(a){a.setAttribute('aria-expanded','false')})}
$$('.nav a[data-dd]').forEach(function(a){
 var k=a.getAttribute('data-dd');
 a.appendChild(el('span','cr'));a.setAttribute('aria-haspopup','true');a.setAttribute('aria-expanded','false');
 a.onclick=function(){
  if(!dd)return true;
  if(ddk===k){ddClose();return false}
  ddClose();ddk=k;dd.className+=' on';a.setAttribute('aria-expanded','true');
  ddFill(k,Q.menu&&Q.menu.done?Q.menu.v:undefined);
  once('menu','/v1/menu.json',function(M){if(ddk===k)ddFill(k,M)});
  return false}});
d.onclick=function(e){
 var t=e?e.target:window.event.srcElement;
 while(t&&t!==d){if(t===dd||(t.getAttribute&&t.getAttribute('data-dd')))return;t=t.parentNode}
 ddClose()};
/* nhom chua co bai nao (Giao dien, Am thanh, Truyen & Meo) thi giau khoi menu cho gon */
once('menu','/v1/menu.json',function(M){
 if(!M||!M.kinds)return;
 $$('.nav a[data-dd]').forEach(function(a){var K=kindOf(M,a.getAttribute('data-dd'));if(K&&!K.count&&K.kind>2)del(a)})});
/* o game: dung chung cho luoi nhan/tim kiem va bang xep hang */
function setIc(th,u,hasShot){
 var i2=el('img',hasShot?'ic2':'ic1');i2.alt='';i2.onerror=function(){del(i2)};i2.src=u;th.appendChild(i2)}
function addDl(th,n){var t=fdl(n);if(t){var s=el('span','dlc',t);th.appendChild(s)}}
/* o game tu list.json: dung chung cho bang xep hang va khoi De xuat tren trang chu. rk = hang (0 = khong hien) */
function mkCell(it,rk){
 var c=el('div','gc'),b=el('div','gcb'),th=el('a','th'),g=el('div','gt'),h=el('h2'),a=el('a','',it.title||''),ch=el('div','chips'),
  tgs=[],j,ts=it.tags||[];
 th.href=it.url||'#';th.title=it.title||'';th.appendChild(el('span','ph','M'));
 if(it.shot){var im=el('img','sc');im.alt='';var ph2=th.querySelector('.ph');im.onerror=function(){del(im);th.className=th.className.replace(' has','');if(ph2)ph2.style.display=''};im.src=API+it.shot;th.appendChild(im);th.className+=' has';if(ph2)ph2.style.display='none'}
 if(it.icon)setIc(th,API+it.icon,!!it.shot);
 if(rk)th.appendChild(el('span','rkn'+(rk<=3?' r'+rk:''),String(rk)));
 if(it.flags&8)th.appendChild(el('span','bd h','HOT'));else if(it.flags&1)th.appendChild(el('span','bd','MỚI'));
 addDl(th,it.dl);
 a.href=it.url||'#';h.appendChild(a);
 for(j=0;j<ts.length;j++){var t=tg(ts[j]);if(t&&tgs.indexOf(t)<0){tgs.push(t);ch.appendChild(el('span','tg',t))}}
 if(it.ver)ch.appendChild(el('span','v','v'+it.ver));
 if(sz(it.sizeKb))ch.appendChild(el('span','',sz(it.sizeKb)));
 if(it.catName)ch.appendChild(el('span','',it.catName));
 g.appendChild(h);g.appendChild(ch);b.appendChild(th);b.appendChild(g);c.appendChild(b);return c}
/* luoi game: anh minh hoa + icon + huy hieu + ban, phien ban, dung luong */
var need=[],GW=vw<600?200:256,GH=vw<600?150:192,now=new Date().getTime(),dlq=[];
$$('.gc').forEach(function(c){
 var r=c.querySelector('.raw'),th=c.querySelector('.th'),ch=c.querySelector('.chips'),
  pre=r.querySelector('pre.mk-meta'),m=pre?meta(pre):{},ph=th.querySelector('.ph'),k;
 $$('span',ch).forEach(function(s){if(/^(game|app|banner)$/i.test(s.textContent))del(s)});
 var add=[];
 if(m.ver)add.push(el('span','v','v'+m.ver));
 if(sz(m.size))add.push(el('span','',sz(m.size)));
 if(m.net==='1')add.push(el('span','','Cần mạng'));
 for(k=0;k<add.length;k++)ch.insertBefore(add[k],ch.childNodes[k]||null);
 addTags(ch,tgList(m.tags));
 /* anh minh hoa: meta img, hoac anh dau tien trong bai khong phai icon Monika (/v1/fi/) */
 var shot=m.img||'',ims=$$('img',r);
 for(k=0;!shot&&k<ims.length;k++){var u=ims[k].getAttribute('src')||'';if(u&&!/\/v1\/fi\//.test(u))shot=u}
 if(shot){var im=el('img','sc');im.alt='';im.onerror=function(){del(im);th.className=th.className.replace(' has','');if(ph)ph.style.display=''};im.src=gimg(lo(shot),GW,GH);th.appendChild(im);th.className+=' has';if(ph)ph.style.display='none'}
 var fk=fileKey(m);
 if(fk)setIc(th,API+'/v1/fi/'+fk+'-64.png',!!shot);
 else need.push({th:th,shot:!!shot,path:th.pathname});
 var t=new Date(c.getAttribute('data-t')).getTime();
 if(m.hot==='1')th.appendChild(el('span','bd h','HOT'));
 else if(!isNaN(t)&&now-t<6048e5)th.appendChild(el('span','bd','MỚI'));
 dlq.push({path:th.pathname.replace(/^\/?/,'/'),set:function(n){addDl(th,n)}});
 del(r)});
if($$('.st').length&&!$$('.gc').length&&$$('.gl').length){var gl=$$('.gl')[0];gl.parentNode.insertBefore(el('div','emp','Chưa có bài nào ở mục này.'),gl.nextSibling)}
/* bai khong co meta file: lay icon trich tu JAR qua API (theo duong dan bai) */
if(need.length){once('icons','/v1/icons.json',function(M){
 if(!M)return;
 need.forEach(function(x){var u=M[x.path];if(u)setIc(x.th,API+u,x.shot)})})}
fillDl(dlq);
/* trang bai: bang thong tin + nut tai */
$$('.pb pre.mk-meta').forEach(function(pre){
 var m=meta(pre),box=el('div','dlbox'),tb=el('table','info'),
  pl=[],ra=String(m.plat||'').split(/[,;]/),i,ch=d.querySelector('.it .chips'),dlt;
 for(i=0;i<ra.length;i++){var pk=ra[i].replace(/\s+/g,'').toLowerCase();if(PL[pk])pl.push(PL[pk])}
 [['Danh mục',m.cat],['Phiên bản',m.ver],['Dung lượng',sz(m.size)],['Nền tảng',pl.join(', ')],['Màn hình',m.res],['Cần mạng',m.net==='1'?'Có':''],['Giá',m.price&&m.price!=='0'?m.price:'']].forEach(function(p){
  if(!p[1])return;var tr=el('tr');tr.appendChild(el('th','',p[0]));tr.appendChild(el('td','',p[1]));tb.appendChild(tr)});
 var tr=el('tr');tr.style.display='none';tr.appendChild(el('th','','Lượt tải'));dlt=el('td');tr.appendChild(dlt);tb.appendChild(tr);
 if(ch)addTags(ch,tgList(m.tags));
 var fk=fileKey(m);
 if(fk){var gi=el('img','gic');gi.alt='';gi.width=64;gi.height=64;gi.src=API+'/v1/fi/'+fk+'-64.png';gi.onerror=function(){del(gi)};box.appendChild(gi)}
 box.appendChild(tb);
 if(m.jar&&/^https?:\/\//i.test(m.jar)){var a=el('a','dlbtn','Tải về (JAR)');a.href=lo(m.jar);a.rel='nofollow noopener';box.appendChild(a)}
 pre.parentNode.insertBefore(box,pre);del(pre);
 fillDl([{path:location.pathname,set:function(n){var t=fdl(n);if(t){dlt.textContent=t;tr.style.display=''}}}])});
/* trang Xep hang (/p/xep-hang.html, trang tinh Blogger de trong): tab + loc + luoi tu list.json */
if(/\/p\/xep-hang\.html$/.test(location.pathname)){(function(){
 var rk=d.getElementById('rk'),art=d.querySelector('.it');
 if(!rk&&art){rk=el('div','rk');rk.id='rk';art.appendChild(rk)}
 if(!rk)return;
 art.className+=' rkp';
 var TABS=[['top1','Hôm nay'],['top7','Tuần'],['dl','Tải nhiều'],['hot','Hot'],['new','Mới']],
  SC=[['all','Tất cả'],['game','Game'],['app','App']],
  PF=[['','Mọi máy'],['1','Java'],['30','S60']],
  S={k:'top7',s:'all',c:0,p:'',g:0},tok=0,cats=null,cur='';
 function rd(){var h=location.hash.replace(/^#/,''),a=h.split('&'),i,kv,v;S.k='top7';S.s='all';S.c=0;S.p='';S.g=0;
  for(i=0;i<a.length;i++){kv=a[i].split('=');v=decodeURIComponent(kv[1]||'');
   if(kv[0]==='k'&&/^(top1|top7|dl|hot|new)$/.test(v))S.k=v;
   else if(kv[0]==='s'&&/^(all|game|app)$/.test(v))S.s=v;
   else if(kv[0]==='c'&&/^\d+$/.test(v))S.c=parseInt(v,10);
   else if(kv[0]==='p'&&/^(1|30)?$/.test(v))S.p=v;
   else if(kv[0]==='g'&&/^\d+$/.test(v))S.g=parseInt(v,10)}}
 function hs(o){var n={k:S.k,s:S.s,c:S.c,p:S.p,g:0},x;for(x in o)n[x]=o[x];
  return '#k='+n.k+'&s='+n.s+'&c='+n.c+'&p='+n.p+'&g='+n.g}
 function key(){var b=S.c?'c'+S.c:(S.s==='all'?'':S.s),k=b?b+'.'+S.k:S.k;if(S.p)k+='.p'+S.p;return k}
 function lk(box,txt,cls,o){var a=el('a',cls,txt);a.href=hs(o);
  a.onclick=function(){for(var x in o)S[x]=o[x];if(o.s!==undefined&&o.c===undefined)S.c=0;if(o.g===undefined)S.g=0;
   try{location.hash=hs({g:S.g})}catch(e){}draw();return false};
  box.appendChild(a);return a}
 var tabs=el('div','tabs'),f1=el('div','fl'),f2=el('div','fl'),f3=el('div','fl'),
  st=el('div'),gl=el('div','gl'),pg=el('div','pg');
 clr(rk);[tabs,f1,f2,f3,st,gl,pg].forEach(function(e){rk.appendChild(e)});
 function filt(box,title,rows,cur,name,extra){
  clr(box);if(!rows.length){box.style.display='none';return}box.style.display='';
  box.appendChild(el('b','',title));
  rows.forEach(function(r){var o={};o[name]=r[0];if(extra)for(var x in extra)o[x]=extra[x];lk(box,r[1],'fb'+(String(cur)===String(r[0])?' on':''),o)})}
 function drawCtl(){
  clr(tabs);TABS.forEach(function(t){lk(tabs,t[1],S.k===t[0]?'on':'',{k:t[0]})});
  filt(f1,'Loại',SC,S.s,'s',{c:0});
  var cr=[];if(S.s!=='all'&&cats){cats.forEach(function(c){if(c.kind===(S.s==='game'?1:2))cr.push([c.id,c.name])});if(cr.length)cr.unshift([0,'Mọi thể loại'])}
  filt(f2,'Thể loại',cr,S.c,'c');
  filt(f3,'Nền tảng',PF,S.p,'p')}
 function cell(it,i){return mkCell(it,S.k!=='new'?S.g*15+i+1:0)}
 function draw(){
  var my=++tok;cur=location.hash;drawCtl();clr(gl);clr(pg);clr(st);
  st.appendChild(el('div','emp','Đang tải bảng xếp hạng...'));
  get(API+'/v1/list.json?key='+encodeURIComponent(key())+'&page='+S.g,function(R){
   if(my!==tok)return;clr(st);
   var L=(R&&R.items)||[],i;
   if(!L.length){st.appendChild(el('div','emp',S.g?'Hết bảng xếp hạng.':'Chưa có mục nào trong bảng này.'));
    if(S.g)lk(pg,'‹ Về trang đầu','',{g:0});return}
   for(i=0;i<L.length;i++)gl.appendChild(cell(L[i],i));
   if(S.g>0)lk(pg,'‹ Trang trước','',{g:S.g-1});
   var more=R.total!=null?(S.g+1)*15<R.total:L.length>=15;
   if(more)lk(pg,'Trang sau ›','o',{g:S.g+1});
   if(!pg.firstChild)pg.style.display='none';else pg.style.display=''},
  function(){if(my!==tok)return;clr(st);
   var e=el('div','emp','Không tải được bảng xếp hạng. '),a=el('a','','Thử lại');a.href=hs({g:S.g});a.onclick=function(){draw();return false};
   e.appendChild(a);st.appendChild(e)})}
 rd();draw();
 window.onhashchange=function(){if(location.hash!==cur){rd();draw()}};
 once('cats','/v1/cats.json',function(C){cats=C||[];drawCtl()})
})()}
$$('.pb img').forEach(function(i){var u=i.getAttribute('src')||'',v=lo(u);if(v!==u)i.src=v});
$$('.pb a').forEach(function(a){var u=a.getAttribute('href')||'',v=lo(u);if(v!==u)a.href=v});
/* trang chu (chi trang dau, khong phai tim kiem/nhan/trang 2+): De xuat hom nay + Top tai nhieu. PC: Top o cot ben; man nho: Top ngay duoi De xuat */
if(/^\/(index\.html)?$/.test(location.pathname)&&!/[?&](q|updated-max|start)=/.test(location.search)&&$$('.gl').length){(function(){
 var hm=d.getElementById('hm'),tp=d.getElementById('tp');
 if(!hm)return;
 var pbox=el('div'),tbox=el('div','tp'),big=vw>=900;
 hm.appendChild(pbox);(big&&tp?tp:hm).appendChild(tbox);
 /* De xuat hom nay: Worker chon cho ca ngay (doi luc nua dem gio Viet Nam) */
 get(API+'/v1/list.json?key=pick&page=0',function(R){
  var L=(R&&R.items)||[];if(!L.length)return;
  L=L.slice(0,vw<600?2:4);
  var h=el('h2','st','Đề xuất hôm nay'),gl=el('div','gl'),t=new Date();
  h.appendChild(el('span','stm',pad(t.getDate())+'/'+pad(t.getMonth()+1)));
  L.forEach(function(it){gl.appendChild(mkCell(it,0))});
  pbox.appendChild(h);pbox.appendChild(gl)});
 /* Top tai nhieu: game, tab Hom nay / Tuan / Moi luc */
 var TT=[['game.top1','Hôm nay'],['game.top7','Tuần'],['game.dl','Mọi lúc']],cur='game.dl',tok=0,head=el('h2','st','Top tải nhiều'),tabs=el('div','tpt'),body=el('div');
 tbox.style.display='none';[head,tabs,body].forEach(function(e){tbox.appendChild(e)});
 function thumb(it){
  var b=el('span','tpi');var u=it.icon?API+it.icon:(it.shot?API+it.shot.replace(/-\d+x\d+\.jpg$/,'-80x60.jpg'):'');
  if(u){var im=el('img');im.alt='';im.width=40;im.height=40;im.onerror=function(){del(im)};im.src=u;b.appendChild(im)}
  return b}
 function row(it,i){
  var a=el('a','tpr'),n=el('span','tpn'+(i<3?' r'+(i+1):''),String(i+1)),x=el('span','tpx'),t=fdl(it.dl),sub=[];
  a.href=it.url||'#';a.appendChild(n);a.appendChild(thumb(it));
  if(t)a.appendChild(el('span','tpd','↓ '+t));
  x.appendChild(el('b','',it.title||''));
  if(it.catName)sub.push(it.catName);if(it.ver)sub.push('v'+it.ver);
  x.appendChild(el('i','',sub.join(' · ')));a.appendChild(x);return a}
 function draw(){
  var my=++tok;clr(tabs);
  TT.forEach(function(t){var a=el('a',t[0]===cur?'on':'',t[1]);a.href='#top';a.onclick=function(){cur=t[0];draw();return false};tabs.appendChild(a)});
  get(API+'/v1/list.json?key='+cur+'&page=0',function(R){
   if(my!==tok)return;
   var L=((R&&R.items)||[]).slice(0,big?10:5),i;
   if(!L.length){if(!body.firstChild)return;clr(body);body.appendChild(el('div','tpe','Chưa có dữ liệu tải.'));return}
   clr(body);tbox.style.display='';
   for(i=0;i<L.length;i++)body.appendChild(row(L[i],i));
   var m=el('a','tpm','Xem bảng xếp hạng đầy đủ ›');m.href='/p/xep-hang.html';body.appendChild(m)})}
 draw()
})()}
/* phan trang so cho trang chu / nhan / tim kiem: Worker tra moc updated-max cua tung trang tu feed Blogger */
if($$('.gc').length&&d.getElementById('pn')){(function(){
 var pn=d.getElementById('pn'),pg=$$('.pg')[0],q=location.search,
  ms=/[?&]start=(\d+)/.exec(q),mr=/[?&]max-results=(\d+)/.exec(q),n=mr?parseInt(mr[1],10):$$('.gc').length,
  cur=ms&&n?Math.floor(parseInt(ms[1],10)/n)+1:1,path=location.pathname,scope='',base='/',lm=/^\/search\/label\/([^\/]+)/.exec(path),qm=/[?&]q=([^&]*)/.exec(q),qs='';
 if(!n)return;
 function dec(x){try{return decodeURIComponent(x.replace(/\+/g,' '))}catch(e){return x}}
 if(lm){scope='label:'+dec(lm[1]);base=path}
 else if(qm){scope='q:'+dec(qm[1]);qs='q='+qm[1]+'&';base='/search?q='+qm[1]}
 if(!lm&&!qm&&!/^\/(index\.html|search)?$/.test(path))return;
 var W=vw<600?4:6;
 get(API+'/v1/pager.json?scope='+encodeURIComponent(scope)+'&n='+n+'&cur='+cur+'&w='+W,function(R){
  if(!R||!R.items||R.pages<2)return;
  var M={},L=R.items,i,last=0;
  for(i=0;i<L.length;i++)M[L[i].p]=L[i].m;
  function href(p){if(p<2)return base;var u=M[p];return u?(lm?path:'/search')+'?'+qs+'updated-max='+encodeURIComponent(u)+'&max-results='+R.n+'&start='+((p-1)*R.n)+'&by-date=false':''}
  function add(t,c,p){var h=p?href(p):'',e=h?el('a',c,t):el('span',c||'dot',t);if(h)e.href=h;pn.appendChild(e)}
  clr(pn);
  if(R.cur>1)add('‹','',R.cur-1);
  for(i=0;i<L.length;i++){var p=L[i].p;if(last&&p>last+1)add('…','dot',0);
   if(p===R.cur)pn.appendChild(el('span','cur',String(p)));else add(String(p),'',p);last=p}
  if(R.cur<R.pages)add('›','',R.cur+1);
  pn.className+=' on';if(pg)pg.className+=' hide'},
 function(){})
})()}
/* banner: chung du lieu voi app Java. Banner dau trang: trong header (man nho) hoac dau cot noi dung (PC), chi nap cai dang hien */
var pc=vw>=900,slots=$$('.bn[data-slot]').filter(function(s){
